import java.util.*;
class Account {private final String name;private final double balance;Account(String n,double b){name=n;balance=b;}String getName(){return name;}double getBalance(){return balance;}public String toString(){return name+" - "+balance;}}
class AccountService {private final List<Account> accounts=new ArrayList<>();void addAccount(Account a){if(a==null)throw new IllegalArgumentException("Account cannot be null");accounts.add(a);}int getCount(){return accounts.size();}Account getAccount(int i){if(i<0||i>=accounts.size())throw new IllegalArgumentException("Invalid account index");return accounts.get(i);}}
public class Main {public static void main(String[] args){Scanner sc=new Scanner(System.in);AccountService service=new AccountService();int choice;do{System.out.println("1. Add Account\n2. View Account Count\n3. Exit\nEnter choice: ");choice=sc.nextInt();sc.nextLine();switch(choice){case 1-> {System.out.print("Name: ");String name=sc.nextLine();System.out.print("Balance: ");double balance=sc.nextDouble();sc.nextLine();service.addAccount(new Account(name,balance));System.out.println("Account added!");}case 2->System.out.println("Total accounts: "+service.getCount());case 3->System.out.println("Exiting...");default->System.out.println("Invalid choice!");}}while(choice!=3);sc.close();}}
